def find_first_occurrence(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            # Move left to find the first occurrence
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left if arr[left] == target else -1

def occurance_substring(text, sub):
    if not text or not sub:
        return None

    start = 0
