def largest_subset(nums):
    if not nums:
        return 0

    # Sort the list to easily check divisibility conditions
    nums.sort()

    n = len(nums)
    # dp[i] will store the size of the largest subset ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            # Check if nums[i] is divisible by nums[j] or vice versa
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

