        return s

    start = s.find(char)
    end = s.rfind(char)

    if start == -1 or end == -1:
        return s

    if start == 0 and end == len(s) - 1:
        return ""
    elif start == 0:
        return s[1:end+1]
    elif end == len(s) - 1:
        return s[:end]
    else:
